hite-space:pre-wrap">{{$t(p.instructions)}}</p><p>{{ $t("可发放库存 ") }}{{$t((p.stockCount || 0))}}{{ $t(" 份") }}</p><el-button v-if="detail.campaign.status==='draft'" :disabled="(p.stockCount||0)>=p.quantity" @click="stockPrize=p;stockText='';stockError=''">{{ $t("导入兑换库存") }}</el-button></template></div><h3>{{ $t("中奖码") }}</h3><div class="rewards-codes"><el-tag v-for="w in detail.winners" :key="w.id">{{$t(w.code)}}</el-tag><span v-if="!detail.winners.length">{{ $t("暂无中奖码") }}</span></div><h3>{{ $t("操作留档") }}</h3><el-table :data="audits"><el-table-column prop="action" :label='$t("操作")'/><el-table-column prop="actor" :label='$t("操作者")'/><el-table-column prop="detail" :label='$t("记录")' min-width="210"/><el-table-column :label='$t("时间")' width="160"><template #default="{row}">{{$t(date(row.createdAt))}}</template></el-table-column></el-table><div class="rewards-pager"><el-button :disabled="auditPage===1" @click="auditPage--;loadAudit()">{{ $t("上一页") }}</el-button><span>{{$t(auditPage)}}</span><el-button :disabled="audits.length<20" @click="auditPage++;loadAudit()">{{ $t("下一页") }}</el-button></div></template></el-dialog>
