interface Audit {id:number;actor:string;action:string;detail:string;createdAt:number}
const phases:Record<string,string>={draft:'草稿',scheduled:'未开始',open:'参与中',paused:'库存不足，已暂停',exhausted:'奖品已抽完',full:'满额待截止',awaiting_draw:'等待开奖',drawn:'已结束',cancelled:'已取消'};const orderStates:Record<string,string>={awaiting_address:'待填写地址',pending:'待发货',shipped:'已发货',completed:'已完成',delivered:'已发放'}
const tab=ref('campaigns'),page=ref(1),kind=ref(''),status=ref(''),loading=ref(false),busy=ref(false),error=ref(''),campaigns=ref<Campaign[]>([]),orders=ref<Order[]>([]),editing=ref(false),formRef=ref<FormInstance>(),detail=ref<Detail|null>(null),audits=ref<Audit[]>([]),auditPage=ref(1),shipping=ref<Order|null>(null),carrier=ref(''),trackingNo=ref('');
const defaults=()=>({id:0,title:'',kind:'pool',prizeName:'',image:'',description:'',rules:'转盘可多次抽奖，每次消耗页面所示积分；奖池每人每期一次。不收现金。参与成功后无论是否中奖均不退回积分，失败不扣分，重复请求不重复扣分。实物奖品由平台包邮，兑换类奖品在“我的奖品”领取并按使用说明兑换。',prizeValue:10000,budget:15000,pointsCost:10,prizeQuantity:1,capacity:100,version:1});const form=reactive(defaults()),prizeYuan=ref(100),budgetYuan=ref(150),starts=ref<Date|null>(null),ends=ref<Date|null>(null);const count=computed(()=>tab.value==='campaigns'?campaigns.value.length:orders.value.length);const date=(n:number)=>new Date(n*1000).toLocaleString(getLanguage(),{hour12:false});const money=(n:number)=>(n/100).toFixed(2);
const prizeKinds:Record<string,string>={physical:'实物奖品',code:'兑换码',link:'兑换券'};
let prizeKey=0;
const newPrize=():PrizeForm=>({key:++prizeKey,id:0,name:'',kind:'physical',image:'',value:1000,valueYuan:10,quantity:1,awardedCount:0,platform:'',instructions:'',expiresAt:0,expiry:null,redemptionUrl:'',stockCount:0});
const wheelSlots=ref<number[]>([]);
const prizes=ref<PrizeForm[]>([]),stockPrize=ref<Prize|null>(null),stockText=ref(''),stockError=ref('');
const totalOddsBps=computed(()=>prizes.value.reduce((n,p)=>n+Math.round((p.probabilityPercent||0)*100),0));
const totalQuantity=computed(()=>form.kind==='wheel'?prizes.value.reduce((n,p)=>n+p.quantity,0):form.prizeQuantity);
const totalValue=computed(()=>form.kind==='wheel'?prizes.value.reduce((n,p)=>n+p.valueYuan*p.quantity,0):prizeYuan.value*form.prizeQuantity);
const stockItems=computed(()=>stockText.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean));
function resetSlots(){const base=[...prizes.value.map((_,i)=>i),...(totalOddsBps.value<10000?[-1]:[])];wheelSlots.value=Array.from({length:10},(_,i)=>base[i%base.length]??-1)}
function validSlots(){return wheelSlots.value.length===10&&wheelSlots.value.every(i=>i===-1||i>=0&&i<prizes.value.length)&&prizes.value.every((_,i)=>wheelSlots.value.includes(i))&&wheelSlots.value.includes(-1)===(totalOddsBps.value<10000)}
watch(()=>[prizes.value.length,totalOddsBps.value<10000],()=>{if(!validSlots())resetSlots()});
function ensurePrizes(){if(form.kind==='wheel'&&!prizes.value.length)prizes.value=[newPrize()]}
async function importStock(){if(!stockPrize.value||!detail.value||busy.value)return;if(!stockItems.value.length){stockError.value='请填写兑换库存';return}busy.value=true;stockError.value='';try{await client.post(`/admin/marketing/rewards/campaigns/${detail.value.campaign.id}/stock`,{prizeId:stockPrize.value.id,items:stockItems.value});stockText.value='';stockPrize.value=null;await inspect(detail.value.campaign);await load();ElMessage.success(uiText('兑换库存已导入'))}catch(e){stockError.value=e instanceof Error?e.message:'导入失败'}finally{busy.value=false}}
async function load(){loading.value=true;error.value='';try{if(tab.value==='campaigns')campaigns.value=await client.get<Campaign[]>(`/admin/marketing/rewards/campaigns`,{params:{page:page.value,kind:kind.value}});else orders.value=await client.get<Order[]>(`/admin/marketing/rewards/orders`,{params:{page:page.value,status:status.value}})}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
function edit(c?:Campaign){Object.keys(form).forEach(k=>delete (form as unknown as Record<string,unknown>)[k]);Object.assign(form,c?{id:c.id,title:c.title,kind:c.kind,prizeName:c.prizeName,image:c.image,description:c.description,rules:c.rules,prizeValue:c.prizeValue,budget:c.budget,pointsCost:c.pointsCost,prizeQuantity:c.prizeQuantity,capacity:c.capacity,version:c.version}:defaults());prizeYuan.value=form.prizeValue/100;budgetYuan.value=form.budget/100;starts.value=new Date(c?c.startsAt*1000:Date.now()+60000);ends.value=new Date(c?c.endsAt*1000:Date.now()+7*86400000);prizes.value=(c?.prizes?.length?c.prizes:c?.kind==='wheel'?[{...newPrize(),name:c.prizeName,image:c.image,value:c.prizeValue,quantity:c.prizeQuantity}]:[]).map(p=>({...p,key:++prizeKey,valueYuan:p.value/100,probabilityPercent:p.probabilityBps==null?undefined:p.probabilityBps/100,expiry:p.expiresAt?new Date(p.expiresAt*1000):null}));ensurePrizes();wheelSlots.value=c?.wheelSlots?.length===10?[...c.wheelSlots]:[];if(!validSlots())resetSlots();editing.value=true}
async function save(){
 const multi=form.kind==='wheel';
 if(multi&&!validSlots()){ElMessage.error(uiText('请完整配置 10 格：每种奖品至少一格，剩余概率须设置谢谢参与'));return}
 if(multi&&(prizes.value.some(p=>!Number.isFinite(p.probabilityPercent)||p.probabilityPercent!<0.01||p.probabilityPercent!>100)||totalOddsBps.value>10000)){ElMessage.error(uiText('请填写每项中奖概率（0.01%–100%），总和不能超过 100%'));return}
 if(!Number.isInteger(form.pointsCost)||form.pointsCost<1||!form.title.trim()||(!multi&&!form.prizeName.trim())||!form.description.trim()||!form.rules.trim()||!starts.value||!ends.value||ends.value.getTime()<=starts.value.getTime()||ends.value.getTime()<=Date.now()||budgetYuan.value<totalValue.value||form.capacity<1||(!multi&&(form.capacity<totalQuantity.value||totalQuantity.value>1000))){ElMessage.error(uiText('请填写完整活动信息，预算须覆盖奖品且截止时间有效'));return}
 if(multi&&(!prizes.value.length||prizes.value.some(p=>!p.name.trim()||p.quantity<1||p.valueYuan<=0||(p.kind!=='physical'&&(!p.platform.trim()||!p.instructions.trim()||!p.expiry||!Number.isFinite(p.expiry.getTime())||p.expiry.getTime()<=ends.value!.getTime()))))){ElMessage.error(uiText('请补全各奖品，兑换有效期须晚于活动截止时间'));return}
 busy.value=true;try{
 const payload={...form,wheelSlots:multi?[...wheelSlots.value]:[],prizes:multi?prizes.value.map(p=>({id:p.id,name:p.name.trim(),kind:p.kind,image:p.image.trim(),value:Math.round(p.valueYuan*100),quantity:p.quantity,probabilityBps:Math.round(p.probabilityPercent!*100),platform:p.kind==='physical'?'':p.platform.trim(),instructions:p.kind==='physical'?'':p.instructions.trim(),expiresAt:p.kind==='physical'?0:Math.floor(p.expiry!.getTime()/1000),redemptionUrl:p.kind==='code'?p.redemptionUrl.trim():''})):[],prizeValue:Math.round(prizeYuan.value*100),budget:Math.round(budgetYuan.value*100),startsAt:Math.floor(starts.value.getTime()/1000),endsAt:Math.floor(ends.value.getTime()/1000)};
 const saved=await (form.id?client.put<Campaign>(`/admin/marketing/rewards/campaigns/${form.id}`,payload):client.post<Campaign>(`/admin/marketing/rewards/campaigns`,payload));
 if(multi&&(JSON.stringify(saved.wheelSlots)!==JSON.stringify(payload.wheelSlots)||saved.prizes?.length!==payload.prizes.length||saved.prizes.some((p,i)=>p.probabilityBps!==payload.prizes[i].probabilityBps))){form.id=saved.id;form.version=saved.version;ElMessage.error(uiText('概率或转盘排布未保存，请联系管理员完成活动服务升级后重试'));await load();return}
 editing.value=false;ElMessage.success(uiText('草稿已保存'));page.value=1;await load();if(saved.prizes?.some(p=>p.kind!=='physical'))await inspect(saved)
 }catch{}finally{busy.value=false}
}
async function transition(c:Campaign,action:string){
 if(action==='publish'&&c.kind==='wheel'&&(!c.prizes?.length||c.prizes.some(p=>!Number.isInteger(p.probabilityBps)||p.probabilityBps!<1||p.probabilityBps!>10000)||c.prizes.reduce((n,p)=>n+(p.probabilityBps||0),0)>10000)){ElMessage.error(uiText('请先编辑并成功保存每项中奖概率，再发布活动'));return}
 try{let payload={};if(action==='cancel'){const r=await ElMessageBox.prompt(uiText('取消后保留记录并向用户显示原因。已有参与的活动不能取消。'),uiText('取消活动'),{confirmButtonText:uiText('确认取消活动'),cancelButtonText:uiText('返回'),inputPlaceholder:uiText('填写取消原因'),inputValidator:v=>!!v&&v.trim().length>=2||'请填写至少两个字的原因'});payload={reason:r.value}}else await ElMessageBox.confirm((action==='publish' ? uiText('发布后参与积分、中奖概率、规则、预算、名额与截止时间冻结。兑换库存须足量，确认平台已准备奖品和履约预算？') : uiText('将对已截止活动执行补偿开奖，已开奖活动不会重复发奖。')),(action==='publish' ? uiText('发布积分活动') : uiText('补偿开奖')),{type:'warning',confirmButtonText:(action==='publish' ? uiText('确认发布') : uiText('确认开奖')),cancelButtonText:uiText('取消')});busy.value=true;await client.post(`/admin/marketing/rewards/campaigns/${c.id}/${action}`,payload);ElMessage.success(uiText('操作完成'));await load()}catch{}finally{busy.value=false}}
async function inspect(c:Campaign){try{detail.value=await client.get<Detail>(`/admin/marketing/rewards/campaigns/${c.id}`);auditPage.value=1;await loadAudit()}catch{}}
async function loadAudit(){if(!detail.value)return;try{audits.value=await client.get<Audit[]>(`/admin/marketing/rewards/campaigns/${detail.value.campaign.id}/audit`,{params:{page:auditPage.value}})}catch{audits.value=[]}}
async function ship(){if(!shipping.value)return;if(!carrier.value.trim()||trackingNo.value.trim().length<3){ElMessage.error(uiText('请填写物流公司和正确单号'));return}busy.value=true;try{await client.post(`/admin/marketing/rewards/orders/${shipping.value.id}/ship`,{carrier:carrier.value.trim(),trackingNo:trackingNo.value.trim()});shipping.value=null;ElMessage.success(uiText('奖品已登记发货'));await load()}catch{}finally{busy.value=false}}
onMounted(load)
</script>
